  public void updateScore(final Player player, final Piece piece, final Move move)
  {
    int dx = Math.abs(move.getSource().getX() - move.getDestination().getX());
    int dy = Math.abs(move.getSource().getY() - move.getDestination().getY());
    int manhattanDistance = dx + dy;
    player.setScore(player.getScore() + manhattanDistance);
  }

